const staleQueuedFiscal = `-- name: StaleQueuedFiscal :many
SELECT id FROM fiscal_receipts WHERE status = 'queued' AND updated_at < now() - interval '5 minutes' ORDER BY created_at
`

// fiscal.reconcile: чеки в queued дольше 5 минут.
func (q *Queries) StaleQueuedFiscal(ctx context.Context) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, staleQueuedFiscal)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

